245	        mockMvc.perform(post("/api/releases/" + releaseId + "/resume").contentType("application/json")
246	                        .content("{\"requestId\":\"r-res1\",\"expectedVersion\":1,\"reason\":\"已修复固件\"}"))
247	                .andExpect(status().isOk())
248	                .andExpect(jsonPath("$.status").value("ACTIVE"))
