253	                .andExpect(jsonPath("$.roundFailed").value(0))
254	                .andExpect(jsonPath("$.roundSuccess").value(0));
255	
256	        // 历史：1 条暂停（轮次1）+ 1 条恢复（新轮次2，含原因与 UTC 时刻）
