260	                .andExpect(jsonPath("$.resumes.length()").value(1))
261	                .andExpect(jsonPath("$.resumes[0].newRound").value(2))
262	                .andExpect(jsonPath("$.resumes[0].reason").value("已修复固件"))
263	                .andReturn();
264	        String resumedAt = com.jayway.jsonpath.JsonPath.read(
265	                history.getResponse().getContentAsString(), "$.resumes[0].resumedAtUtc");
266	        org.assertj.core.api.Assertions.assertThat(resumedAt).endsWith("Z");
267	
268	        // 恢复不重开 FAILED 任务：d1 拉取仍返回原 FAILED 任务
269	        mockMvc.perform(post("/api/devices/d1/pull").contentType("application/json")
270	                        .content("{\"requestId\":\"r-pull1b\"}"))
271	                .andExpect(status().isOk())
272	                .andExpect(jsonPath("$.task.taskId").value(t1))
273	                .andExpect(jsonPath("$.task.status").value("FAILED"));
274	
275	        // 恢复后按原比例继续投放新设备
276	        long t3 = pullTask("r-pull3", "d3");
