package com.example.starter.firmware.error;

import org.springframework.http.HttpStatus;

/**
 * 业务异常，携带 HTTP 状态码与稳定错误码。
 */
public class ApiException extends RuntimeException {

    private final HttpStatus status;
    private final String code;

    public ApiException(HttpStatus status, String code, String message) {
        super(message);
        this.status = status;
        this.code = code;
    }

    public HttpStatus status() {
        return status;
    }

    public String code() {
        return code;
    }

    public static ApiException badRequest(String code, String message) {
        return new ApiException(HttpStatus.BAD_REQUEST, code, message);
    }

    public static ApiException notFound(String code, String message) {
        return new ApiException(HttpStatus.NOT_FOUND, code, message);
    }

    public static ApiException conflict(String code, String message) {
        return new ApiException(HttpStatus.CONFLICT, code, message);
    }

    /**
     * 422：请求语义正确但业务校验不通过（设备不信任证书链、兼容性拒绝、当前无有效证书链等）。
     */
    public static ApiException unprocessable(String code, String message) {
        return new ApiException(HttpStatus.UNPROCESSABLE_ENTITY, code, message);
    }
}

package com.example.starter.firmware.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

/**
 * 固件版本登记请求。登记后该固件版本纳入签名证书链管理。
 */
public record RegisterFirmwareRequest(
        @NotBlank @Size(max = 64) String requestId,
        @NotBlank @Size(max = 64) String model,
        @NotBlank @Size(max = 64) String version,
        @NotBlank @Size(max = 64) String operator) {
}

package com.example.starter.firmware.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

import java.util.List;

/**
 * 首个签名证书链登记请求。chainVersion 必须为 1；区间为闭开区间 [validFromUtc, validToUtc)，
 * validToUtc 传 null 表示开放区间。deviceIds 为创建时刻即信任该链的设备集合（须已登记）。
 */
public record RegisterCertChainRequest(
        @NotBlank @Size(max = 64) String requestId,
        @NotBlank @Size(max = 64) String model,
        @NotBlank @Size(max = 64) String firmwareVersion,
        @NotNull Integer chainVersion,
        @Size(max = 256) String certFingerprint,
        @NotBlank @Size(max = 40) String validFromUtc,
        @Size(max = 40) String validToUtc,
        @NotNull List<@NotBlank @Size(max = 64) String> deviceIds,
        @NotBlank @Size(max = 64) String operator) {
}

package com.example.starter.firmware.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

import java.util.List;

/**
 * 证书链轮换请求：必须显式指定旧链版本与新链版本。旧开放链在新链生效时刻闭合，
 * 区间首尾相接不重叠；deviceIds 为轮换时刻授权信任新链的设备集合。
 */
public record RolloverCertChainRequest(
        @NotBlank @Size(max = 64) String requestId,
        @NotBlank @Size(max = 64) String model,
        @NotBlank @Size(max = 64) String firmwareVersion,
        @NotNull Integer oldChainVersion,
        @NotNull Integer newChainVersion,
        @NotBlank @Size(max = 256) String certFingerprint,
        @NotBlank @Size(max = 40) String validFromUtc,
        @NotNull List<@NotBlank @Size(max = 64) String> deviceIds,
        @NotBlank @Size(max = 64) String operator) {
}

package com.example.starter.firmware.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * 证书链撤销请求。撤销后新拉取不得使用该链；已固化该链的在途任务仍可回执，但须人工复核。
 */
public record RevokeCertChainRequest(
        @NotBlank @Size(max = 64) String requestId,
        @NotBlank @Size(max = 64) String model,
        @NotBlank @Size(max = 64) String firmwareVersion,
        @NotNull Integer chainVersion,
        @NotBlank @Size(max = 256) String reason,
        @NotBlank @Size(max = 64) String operator) {
}

package com.example.starter.firmware.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * 兼容矩阵登记/覆盖请求：某型号从 fromVersion 到 toVersion 是否允许投放。
 */
public record UpsertCompatRequest(
        @NotBlank @Size(max = 64) String requestId,
        @NotBlank @Size(max = 64) String model,
        @NotBlank @Size(max = 64) String fromVersion,
        @NotBlank @Size(max = 64) String toVersion,
        @NotNull Boolean allowed,
        @NotBlank @Size(max = 64) String operator) {
}

package com.example.starter.firmware.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.Size;

import java.util.List;

/**
 * 批量启动请求：先校验全体设备的证书链、信任集合与兼容性，任一不过则全部任务不创建。
 */
public record BatchStartRequest(
        @NotBlank @Size(max = 64) String requestId,
        @NotEmpty List<@NotBlank @Size(max = 64) String> deviceIds,
        @NotBlank @Size(max = 64) String operator) {
}

package com.example.starter.firmware.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * 撤销链回执的人工复核请求：CONFIRMED 人工确认（SUCCESS 回执据此更新设备版本）；REJECTED 人工拒绝。
 */
public record TaskReviewRequest(
        @NotBlank @Size(max = 64) String requestId,
        @NotNull ReviewAction action,
        @NotBlank @Size(max = 256) String reason,
        @NotBlank @Size(max = 64) String operator) {

    /**
     * 复核动作。
     */
    public enum ReviewAction {
        CONFIRMED,
        REJECTED
    }
}

